def parse_duration(s: str) -> int:
    # 1. Handle whitespace and empty string
    s_stripped = s.strip()
    if not s_stripped:
        raise ValueError("Empty duration string")

    # 2. Validate allowed characters (digits, units, whitespace)
    if re.search(r'[^0-9dhmsDHMS\s]', s):
        raise ValueError("Invalid characters")

    # 3. Normalize: remove whitespace and lowercase
    s_normalized = "".join(s.split()).lower()

    if not s_normalized:
        raise ValueError("Empty duration string")

    # 4. Find all [digits][unit] pairs
    matches = list(re.findall(r'(\d+)([dhms])', s_normalized))

    # Ensure the entire string is composed only of these [number][unit] blocks.
    reconstructed = "".join(m[0] + m[1] for m in matches)
    if reconstructed != s_normalized:
        raise ValueError("Invalid format: must be a sequence of [number][unit] blocks")

    # 5. Validate uniqueness and order
    units_order = {'d': 4, 'h': 3, 'm': 2, 's': 1}
    seen_units = set()
    last_order = 5  # Higher than any possible order

    total_seconds = 0

    for value_str, unit in matches:
        value = int(value_str)

        if unit in seen_units:
            raise ValueError(f"Repeated unit: {unit}")
        seen_units.add(unit)

        current_order = units_order[unit]
        if current_order >= last_order:
            raise ValueError("Units must be in descending order")

        last_order = current_order

        # Calculate seconds
        if unit == 'd':
            total_seconds += value * 86400
        elif unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds

def format_duration(seconds: int) -> str:
    # Validate input type (must be int, but not bool)
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("Input must be an integer")

    if seconds < 0:
        raise ValueError("Input must be a non-negative integer")

    if seconds == 0:
        return "0s"

    # Units and their values in seconds
    units = [
        ('d', 86400),
        ('h', 3600),
        ('m', 60),
        ('s', 1)
    ]

    parts = []
    remaining = seconds

    for unit_char, unit_seconds in units:
        if remaining >= unit_seconds:
            value = remaining // unit_seconds
            remaining %= unit_seconds
            parts.append(f"{value}{unit_char}")

    return "".join(parts)
